// Deterministic, uncompressed ZIPs for small, reviewable documentation sources.
// No private key or signature is generated by the website build.
import { Buffer } from 'node:buffer';
const crcTable=Array.from({length:256},(_,value)=>{
  let crc=value;
  for(let bit=0;bit<8;bit++) crc=(crc&1)?0xedb88320^(crc>>>1):crc>>>1;
  return crc>>>0;
});
const crc32=bytes=>{
  let crc=0xffffffff;
  for(const byte of bytes) crc=crcTable[(crc^byte)&255]^(crc>>>8);
  return (crc^0xffffffff)>>>0;
};
export function sourceArchive(files){
  const local=[],central=[];
  let offset=0;
  const entries=Object.entries(files).sort(([a],[b])=>a.localeCompare(b,'en'));
  if(entries.length>4096) throw new Error('Too many example archive files');
  for(const [path,value] of entries){
    if(!/^[a-zA-Z0-9_./-]+$/.test(path)||path.startsWith('/')||path.split('/').some(part=>!part||part==='.'||part==='..')) throw new Error('Unsafe example archive path: '+path);
    const name=Buffer.from(path),bytes=Buffer.isBuffer(value)?value:Buffer.from(value);
    const crc=crc32(bytes),header=Buffer.alloc(30);
    header.writeUInt32LE(0x04034b50);header.writeUInt16LE(20,4);header.writeUInt16LE(0x800,6);
    header.writeUInt16LE(0,8);header.writeUInt16LE(0,10);header.writeUInt16LE(33,12);
    header.writeUInt32LE(crc,14);header.writeUInt32LE(bytes.length,18);header.writeUInt32LE(bytes.length,22);header.writeUInt16LE(name.length,26);
    local.push(header,name,bytes);
    const index=Buffer.alloc(46);
    index.writeUInt32LE(0x02014b50);index.writeUInt16LE(0x314,4);index.writeUInt16LE(20,6);index.writeUInt16LE(0x800,8);
    index.writeUInt16LE(0,10);index.writeUInt16LE(0,12);index.writeUInt16LE(33,14);index.writeUInt32LE(crc,16);
    index.writeUInt32LE(bytes.length,20);index.writeUInt32LE(bytes.length,24);index.writeUInt16LE(name.length,28);
    index.writeUInt32LE(0x81a40000,38);index.writeUInt32LE(offset,42);
    central.push(index,name);offset+=header.length+name.length+bytes.length;
  }
  const directory=Buffer.concat(central),end=Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50);end.writeUInt16LE(entries.length,8);end.writeUInt16LE(entries.length,10);
  end.writeUInt32LE(directory.length,12);end.writeUInt32LE(offset,16);
  return Buffer.concat([...local,directory,end]);
}
